# hairpin1 loop 8-11 closing (7,12) tetraloop GAAA
# hairpin2 loop 17-19 closing (16,20) triloop
# closing pairs C-G, others G-C
seq=list('A'*29)
caps={(7,12):'GAAA',(16,20):'GAA'}
for (cl,cr),m in caps.items():
    for k,pos in enumerate(range(cl+1,cr)):
        seq[pos]=m[k]
closing={(7,12),(16,20)}
pairs=[(0,28),(1,27),(3,26),(4,25),(6,13),(7,12),(15,21),(16,20)]
for (i,j) in pairs:
    if (i,j) in closing:
        seq[i]='C';seq[j]='G'
    else:
        seq[i]='G';seq[j]='C'
# unpaired positions: 2,5,14,22,23,24 -> A
print(''.join(seq))
"

